#!/usr/bin/env bash
# Question 3: Worker after a configuration change. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

case "${Q3_FAULT}" in
  kubelet-client-ca)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q3_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q3_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
  runtime-endpoint)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q3_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q3_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
  kubelet-config-flag)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q3_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q3_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
  kubelet-kubeconfig-flag)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q3_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q3_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
  kubelet-serving-cert)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q3_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q3_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
  kubelet-eviction-hard)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q3_NODE}" -o jsonpath='{.status.conditions[?(@.type=="MemoryPressure")].status}' 2>/dev/null || true)" == True ]] && exit 0
      sleep 2
    done
    echo "the node never reported MemoryPressure" >&2
    exit 1
    ;;
  kubelet-cgroup-driver)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q3_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && kubectl get node "${Q3_NODE}" -o jsonpath='{range .spec.taints[?(@.effect=="NoSchedule")]}{.key}{"\n"}{end}' | grep -qE '^node.kubernetes.io/(unreachable|not-ready)$' && exit 0
      sleep 2
    done
    echo "the node is still Ready, or not yet tainted" >&2
    exit 1
    ;;
esac
